# -*- coding: utf-8 -*-
# Задание №6: эталонное решение ученика (Python). Независимая реализация: направление — комплексное число, внутренность — индекс обхода.
# Запуск: python solve.py запрос.json   (формат запроса — см. tests/*.json)
import sys, json, cmath
from math import gcd, pi


def execute(prog):
    z, d, down = 0j, 1j, True              # позиция, направление (вверх = i), хвост
    lines = [[z]]

    def go(cs):
        nonlocal z, d, down
        for c in cs:
            t = c[0]
            if t == 'rep':
                for _ in range(c[1]):
                    go(c[2])
            elif t == 'F':
                z += c[1] * d
                if down:
                    lines[-1].append(z)
            elif t == 'R':
                d *= cmath.exp(-1j * c[1] * pi / 180)
            elif t == 'L':
                d *= cmath.exp(1j * c[1] * pi / 180)
            elif t == 'up':
                down = False
            else:
                down = True
                lines.append([z])
    go(prog)
    return lines


def first_lap(line):
    for i in range(1, len(line)):
        if abs(line[i] - line[0]) < 1e-7:
            return line[:i]


def dist(p, a, b):                          # расстояние от точки до отрезка
    ab = b - a
    t = max(0, min(1, ((p - a) * ab.conjugate()).real / abs(ab) ** 2))
    return abs(p - (a + t * ab))


def on_line(p, poly):
    return any(dist(p, poly[i], poly[(i + 1) % len(poly)]) < 1e-7 for i in range(len(poly)))


def winding(p, poly):                       # индекс обхода: 0 — снаружи
    w = 0
    for i in range(len(poly)):
        a, b = poly[i] - p, poly[(i + 1) % len(poly)] - p
        if a.imag <= 0 < b.imag and (a.conjugate() * b).imag > 0:
            w += 1
        elif b.imag <= 0 < a.imag and (a.conjugate() * b).imag < 0:
            w -= 1
    return w


def main():
    q = json.load(open(sys.argv[1], encoding="utf-8"))
    kind, form = q["kind"], q["form"]
    if kind == 'D':
        moves, k = q["moves"], q["k"]
        if form == 'traj':
            x = y = 0
            s = {(0, 0)}
            for _ in range(k):
                for a, b in moves:
                    g = gcd(abs(a), abs(b))
                    s |= {(x + a // g * t, y + b // g * t) for t in range(1, g + 1)}
                    x += a; y += b
            print(len(s))
        else:
            P = [0j]
            for a, b in moves[:-1]:
                P.append(P[-1] + complex(a, b))
            print(sum(1 for X in range(-40, 41) for Y in range(-40, 41)
                      if winding(complex(X, Y), P) != 0 and not on_line(complex(X, Y), P)))
        return
    lines = execute(q["prog"])
    polys = [first_lap(l) for l in lines if len(l) > 2]
    if kind == 'R':
        def box(p):
            return min(round(v.real) for v in p), max(round(v.real) for v in p), min(round(v.imag) for v in p), max(round(v.imag) for v in p)
        (a1, b1, c1, d1), (a2, b2, c2, d2) = box(polys[0]), box(polys[1])
        w, h = min(b1, b2) - max(a1, a2), min(d1, d2) - max(c1, c2)
        print(2 * (w + h) if form == 'perim' else w * h)
        return
    strict = form.endswith('strict') or form == 'strict'
    mode = 'union' if form.startswith('union') else ('inter' if form.startswith('inter') else 'one')
    cnt = 0
    for X in range(-60, 61):
        for Y in range(-60, 61):
            p = complex(X, Y)
            m = [(winding(p, P) != 0 and not on_line(p, P)) if strict else (winding(p, P) != 0 or on_line(p, P)) for P in polys]
            ok = all(m) if mode == 'inter' else (any(m) if mode == 'union' else m[0])
            cnt += ok
    print(cnt)


main()

