prog = [
    ('R', 90),
    ('rep', 7, [('F', 11), ('R', 45), ('F', 8), ('R', 135)])]

from math import cos, sin, radians

def flat(prog):                              # раскрываем «Повтори» в плоский список команд
    for c in prog:
        if c[0] == 'rep':
            for _ in range(c[1]):
                yield from flat(c[2])
        else:
            yield c

x, y, ang, down = 0.0, 0.0, 90, True         # старт: (0, 0), голова вдоль OY (угол 90°)
lines = [[(x, y)]]                           # каждая линия при опущенном хвосте — список вершин
for c in flat(prog):
    if c[0] == 'F':
        x += c[1] * cos(radians(ang)); y += c[1] * sin(radians(ang))
        if down:
            lines[-1].append((x, y))
    elif c[0] == 'R':
        ang -= c[1]                          # «Направо» — по часовой стрелке
    elif c[0] == 'L':
        ang += c[1]
    elif c[0] == 'up':
        down = False
    else:
        down = True
        lines.append([(x, y)])

def polygon(line):                           # вершины первого обхода (до возврата в начало)
    for i in range(1, len(line)):
        if abs(line[i][0] - line[0][0]) < 1e-7 and abs(line[i][1] - line[0][1]) < 1e-7:
            return line[:i]

def on_edge(px, py, poly):                   # точка лежит на линии?
    for i in range(len(poly)):
        (x1, y1), (x2, y2) = poly[i], poly[(i + 1) % len(poly)]
        dx, dy = x2 - x1, y2 - y1
        t = max(0, min(1, ((px - x1) * dx + (py - y1) * dy) / (dx * dx + dy * dy)))
        if (px - x1 - t * dx) ** 2 + (py - y1 - t * dy) ** 2 < 1e-12:
            return True
    return False

def inside(px, py, poly):                    # луч вправо: нечётное число пересечений — внутри
    res = False
    for i in range(len(poly)):
        (x1, y1), (x2, y2) = poly[i], poly[(i + 1) % len(poly)]
        if (y1 > py) != (y2 > py) and px < x1 + (py - y1) * (x2 - x1) / (y2 - y1):
            res = not res
    return res

polys = [polygon(l) for l in lines if len(l) > 2]

print(sum(1 for X in range(-60, 61) for Y in range(-60, 61)
          if inside(X, Y, polys[0]) and not on_edge(X, Y, polys[0])))

